        "note": "地方藍營（含謝龍介等）長期在議會與選戰批評治水成效與「一淹就怪雨大、再哭預算不夠」；要求監督治水預算與執行。",
        "plain": "簡單講：該做的防水工程可以做，但花了多少、淹水有沒有真的變少，要講清楚給大家看。不能一下雨就只怪雨太大；工程蓋在哪、有沒有人維修，還有蓋光電或新建案有沒有堵住排水，都要檢討，也要跟中央要到真正有用的錢。"
